import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"FR 3.5.8 - Track Content Request Status","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-8-track-request-status/spec.md","filePath":"feature/media-package-campaign/3-5-8-track-request-status/spec.md"}'),o={name:"feature/media-package-campaign/3-5-8-track-request-status/spec.md"};function c(n,e,i,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="fr-3-5-8-track-content-request-status" tabindex="-1">FR 3.5.8 - Track Content Request Status <a class="header-anchor" href="#fr-3-5-8-track-content-request-status" aria-label="Permalink to &quot;FR 3.5.8 - Track Content Request Status&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Status</td><td>Depends on FR 3.5.7 V2 migration and E51-01</td></tr><tr><td>Roles</td><td>Manager; Client read-only</td></tr><tr><td>Delivery task</td><td>DA-E50-10</td></tr></tbody></table><h2 id="outcome" tabindex="-1">Outcome <a class="header-anchor" href="#outcome" aria-label="Permalink to &quot;Outcome&quot;">​</a></h2><p>Manager moves a content request through <code>PENDING</code>, <code>IN_PROGRESS</code>, <code>ACCEPTED</code>, or <code>DENIED</code>. On first acceptance, the system creates exactly one backlog task.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Only an authorised Manager changes status; Client can read it only.</li><li>Confirmed 2026-10-13: <code>PENDING -&gt; IN_PROGRESS</code> is triggered only when Manager explicitly clicks <strong>Tiếp nhận yêu cầu</strong>. Opening a list/detail page never changes state.</li><li><code>IN_PROGRESS</code> displays as <strong>Đang xem xét</strong>; it is request review, not Task execution. Record the reviewing actor and time. The Client loses edit/cancel permission immediately upon successful receipt.</li><li>Only <code>PENDING -&gt; IN_PROGRESS</code>, <code>IN_PROGRESS -&gt; ACCEPTED</code>, <code>IN_PROGRESS -&gt; DENIED</code>, and creator cancellation <code>PENDING -&gt; CANCELLED</code> are supported; no direct accept/deny from <code>PENDING</code>. Terminal states never reopen.</li><li>Acceptance is idempotent and creates a generic task with <code>campaignId: null</code>, copied type/due date, and <code>sourceType=CONTENT_REQUEST</code> plus <code>sourceRefId</code>.</li><li>A list/detail read model lets both permitted parties track the result.</li><li>Do not report successful acceptance unless the generated Task is durably present and linked. Retried acceptance returns the same Task, without overwriting its subsequent execution state.</li></ul><h2 id="ui-contract" tabindex="-1">UI contract <a class="header-anchor" href="#ui-contract" aria-label="Permalink to &quot;UI contract&quot;">​</a></h2><p>Use parallel vi/en <code>requests.v2.status.*</code>, <code>requests.v2.review.*</code>, <code>requests.v2.generatedTask</code> and <code>requests.v2.taskStatus.*</code> keys. Show actions by server capabilities derived from effective Workspace role. Confirm irreversible accept/deny, disable writes while loading, retain denial note on conflict, and use semantic light/dark tokens with keyboard-accessible controls. <code>GET /{id}/task</code> gives Request readers a read-only Task summary; only a Workspace Manager with POST sees an editor link. Client does not gain editor or assignment permissions. Assignment and Task approval belong to E51, not to Request statuses.</p><p>Confirmed during phase 3: a new Task keeps existing defaults — BACKLOG, no Creator/QC, <code>requiresClientApproval=false</code>, empty typeMetadata and approvalRound 1. Manager configures Task details later. Optional denial note is plain text &lt;=2000 and visible to the Client.</p>',9)])])}const m=t(o,[["render",c]]);export{h as __pageData,m as default};
